const kills = [];
let n = 0;
const start = Date.now();
while (Date.now() - start < 240000 && n < 40) {
  const res = await bot.attack(/^(Man|Rat|Goblin|Chicken|Cow)$/i, 8000);
  n++;
  if (!res.success) { kills.push(res.reason); if (kills.length > 5) break; }
  await new Promise(r => setTimeout(r, 500));
}
return { first: r, n, fails: kills.slice(-5), inv: sdk.getInventory().length, hp: sdk.getState()?.hp };

